#nullable enable
using Marten;
using Marten.Schema;
using HourBooking.Contracts;

namespace HourBooking.IntegrationTests;

/// <summary>
/// Fixed ids so a GIVEN can name things and a failing test is reproducible. The model declares field
/// names and types but never example values — this is where the values live, once, instead of being
/// invented per test.
///
/// Seeds only the events nothing in this system produces: the genesis membership and calendar facts,
/// which carry origin= rather than from= precisely because we have no control over them. Everything
/// else is appended by a test's own GIVEN, because that is what a GIVEN is for.
/// </summary>
public sealed class SeedData : IInitialData
{
    public static readonly Guid EmployeeId = Guid.Parse("11111111-1111-1111-1111-111111111111");
    public static readonly Guid OtherEmployeeId = Guid.Parse("22222222-2222-2222-2222-222222222222");
    public static readonly Guid ProjectId = Guid.Parse("33333333-3333-3333-3333-333333333333");
    public static readonly Guid LeftProjectId = Guid.Parse("44444444-4444-4444-4444-444444444444");
    public static readonly Guid AdminId = Guid.Parse("55555555-5555-5555-5555-555555555555");

    public const string Month = "2026-08";
    public const string EmployeeName = "Ada Lovelace";
    public static readonly DateOnly WorkingDay = new(2026, 8, 3);
    public static readonly DateOnly SecondWorkingDay = new(2026, 8, 4);
    public static readonly DateTimeOffset SeededAt = new(2026, 8, 1, 0, 0, 0, TimeSpan.Zero);

    /// <summary>Membership is seeded per (employee, project) — the grain of the MyProjects view.</summary>
    public static string MembershipStream(Guid employeeId, Guid projectId) => $"membership:{employeeId}:{projectId}";

    public async Task Populate(IDocumentStore store, CancellationToken cancellation)
    {
        await using var session = store.LightweightSession();

        // A project the employee belongs to, and one they have left. Two rows in MyProjects, which is
        // what lets NotAProjectMember be tested without inventing anything.
        session.Events.Append(MembershipStream(EmployeeId, ProjectId),
            new EmployeeAssignedToProject(EmployeeId, ProjectId, "Apollo", SeededAt));

        session.Events.Append(MembershipStream(EmployeeId, LeftProjectId),
            new EmployeeAssignedToProject(EmployeeId, LeftProjectId, "Gemini", SeededAt),
            new EmployeeRemovedFromProject(EmployeeId, LeftProjectId, WorkingDay, SeededAt));

        await session.SaveChangesAsync(cancellation);
    }
}
